const q=document.getElementById('q'),yr=document.getElementById('yr'),go=document.getElementById('go'),st=document.getElementById('status'),resEl=document.getElementById('results'),keptEl=document.getElementById('kept'),emptyEl=document.getElementById('empty');
let kept=[],revs={},results=[];
function setStatus(t,err){st.textContent=t;st.className=err?'err':'';}
function isKept(m){for(const k of kept){if((k.movieId&&k.movieId===m.movieId)||(k.title===m.title&&k.year===m.year))return true;}return false;}
async function load(){const r=await tessera.call('data.read',{});kept=(r.data.watchlist||[]);revs=(r.revisions.watchlist||{});renderKept();}
function info(m){const d=document.createElement('div');d.className='info';const t=document.createElement('div');t.className='t';t.textContent=m.title;const mt=document.createElement('div');mt.className='meta';mt.textContent=m.year?String(m.year):'Year unknown';d.appendChild(t);d.appendChild(mt);return [d,t];}
function renderKept(){keptEl.textContent='';emptyEl.hidden=kept.length>0;for(const k of kept){const li=document.createElement('li');li.setAttribute('data-hook','kept');const [d]=info(k);if(k.overview){const p=document.createElement('p');p.className='ov';p.textContent=k.overview;d.appendChild(p);}const b=document.createElement('button');b.type='button';b.className='sec';b.textContent='Remove';b.setAttribute('aria-label','Remove '+k.title+' from watchlist');b.addEventListener('click',()=>removeIt(k));li.appendChild(d);li.appendChild(b);keptEl.appendChild(li);}renderResults();}
function renderResults(){resEl.textContent='';for(const m of results){const li=document.createElement('li');li.setAttribute('data-hook','result');const [d,t]=info(m);t.setAttribute('data-hook','result-title');if(m.overview){const p=document.createElement('p');p.className='ov';p.textContent=m.overview;d.appendChild(p);}const b=document.createElement('button');b.type='button';b.setAttribute('data-hook','result-keep');const was=isKept(m);b.textContent=was?'Kept':'Keep';b.setAttribute('aria-label',(was?'Already kept: ':'Keep ')+m.title);if(was)b.className='sec';b.addEventListener('click',()=>keep(m));li.appendChild(d);li.appendChild(b);resEl.appendChild(li);}}
async function keep(m){if(isKept(m)){setStatus('"'+m.title+'" is already on your watchlist.');return;}try{await tessera.call('data.patch',{operations:[{op:'add',collection:'watchlist',record:{movieId:m.movieId,title:m.title,year:m.year,overview:m.overview}}]});await load();setStatus('Kept "'+m.title+'".');}catch(e){setStatus('Could not keep it: '+(e&&e.message?e.message:'try again.'),true);}}
async function removeIt(k){try{await tessera.call('data.patch',{operations:[{op:'remove',collection:'watchlist',id:k.id,revisionCount:revs[k.id]}]});await load();setStatus('Removed "'+k.title+'".');}catch(e){setStatus('Could not remove it: '+(e&&e.message?e.message:'try again.'),true);}}
function parse(body){let j;try{j=JSON.parse(body);}catch(e){return null;}const arr=Array.isArray(j)?j:(Array.isArray(j.results)?j.results:null);if(!arr)return null;const out=[];for(const x of arr){if(!x||typeof x!=='object')continue;const title=String(x.title||x.name||'').trim();if(!title)continue;const ds=String(x.release_date||x.year||'');const y=parseInt(ds.slice(0,4),10);out.push({movieId:String(x.id!==undefined?x.id:''),title:title,year:isNaN(y)?null:y,overview:typeof x.overview==='string'?x.overview:''});}return out;}
async function search(){const term=q.value.trim();if(!term){setStatus('Type a title or topic to search for.',true);q.focus();return;}setStatus('Searching…');go.disabled=true;try{const r=await tessera.call('connection.request',{connection:'movies',method:'GET',path:'/search/movie?query='+encodeURIComponent(term)});if(r.statusCode<200||r.statusCode>=300){results=[];renderResults();setStatus('The film service answered with an error ('+r.statusCode+'). Try again later.',true);return;}const all=parse(r.body);if(!all){results=[];renderResults();setStatus('The film service gave an answer this tool could not read.',true);return;}const max=parseInt(yr.value,10);results=all.filter(m=>m.year===null||m.year<max);renderResults();setStatus(results.length?results.length+' film'+(results.length===1?'':'s')+' found. Source: movies service.':'No films found before that year. Try another search or a later year.');}catch(e){results=[];renderResults();setStatus('Could not reach the film service: '+(e&&e.message?e.message:'try again.'),true);}finally{go.disabled=false;}}
go.addEventListener('click',search);
q.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();search();}});
load().catch(()=>setStatus('Could not load your watchlist.',true));

